{
  UNITY_LINE_TYPE cmock_line = TEST_LINE_NUM;
  CMOCK_PLAT_CAN_Create_CALL_INSTANCE* cmock_call_instance;
  UNITY_SET_DETAIL(CMockString_PLAT_CAN_Create);
  cmock_call_instance = (CMOCK_PLAT_CAN_Create_CALL_INSTANCE*)CMock_Guts_GetAddressFor(Mock.PLAT_CAN_Create_CallInstance);
  Mock.PLAT_CAN_Create_CallInstance = CMock_Guts_MemNext(Mock.PLAT_CAN_Create_CallInstance);
  if (Mock.PLAT_CAN_Create_IgnoreBool && cmock_call_instance != NULL &&
      cmock_call_instance->ReturnThruPtr_ctx_Used)
  {
    UNITY_TEST_ASSERT_NOT_NULL(ctx, cmock_line, CMockStringPtrIsNULL);
    CMOCK_MEMCPY((void*)ctx, (const void*)cmock_call_instance->ReturnThruPtr_ctx_Val,
      cmock_call_instance->ReturnThruPtr_ctx_Size);
  }
  if (Mock.PLAT_CAN_Create_IgnoreBool)
  {
    UNITY_CLR_DETAILS();
    if (cmock_call_instance == NULL)
      return Mock.PLAT_CAN_Create_FinalReturn;
    Mock.PLAT_CAN_Create_FinalReturn = cmock_call_instance->ReturnVal;
    return cmock_call_instance->ReturnVal;
  }
  if (!Mock.PLAT_CAN_Create_CallbackBool &&
      Mock.PLAT_CAN_Create_CallbackFunctionPointer != NULL)
  {
    CAN_Instance_s* cmock_cb_ret = Mock.PLAT_CAN_Create_CallbackFunctionPointer(ops, ctx, Mock.PLAT_CAN_Create_CallbackCalls++);
    UNITY_CLR_DETAILS();
    return cmock_cb_ret;
  }
  UNITY_TEST_ASSERT_NOT_NULL(cmock_call_instance, cmock_line, CMockStringCalledMore);
  cmock_line = cmock_call_instance->LineNumber;
  if (cmock_call_instance->CallOrder > ++GlobalVerifyOrder)
    UNITY_TEST_FAIL(cmock_line, CMockStringCalledEarly);
  if (cmock_call_instance->CallOrder < GlobalVerifyOrder)
    UNITY_TEST_FAIL(cmock_line, CMockStringCalledLate);
  if (!cmock_call_instance->ExpectAnyArgsBool)
  {
  if (!cmock_call_instance->IgnoreArg_ops)
  {
    UNITY_SET_DETAILS(CMockString_PLAT_CAN_Create,CMockString_ops);
    UNITY_TEST_ASSERT_EQUAL_MEMORY(cmock_call_instance->Expected_ops, ops, sizeof(const CAN_Ops_s), cmock_line, CMockStringMismatch);
  }
  if (!cmock_call_instance->IgnoreArg_ctx)
  {
    UNITY_SET_DETAILS(CMockString_PLAT_CAN_Create,CMockString_ctx);
    UNITY_TEST_ASSERT_EQUAL_PTR(cmock_call_instance->Expected_ctx, ctx, cmock_line, CMockStringMismatch);
  }
  }
  if (Mock.PLAT_CAN_Create_CallbackFunctionPointer != NULL)
  {
    UNITY_SET_DETAIL(CMockString_PLAT_CAN_Create);
    cmock_call_instance->ReturnVal = Mock.PLAT_CAN_Create_CallbackFunctionPointer(ops, ctx, Mock.PLAT_CAN_Create_CallbackCalls++);
  }
  if (cmock_call_instance->ReturnThruPtr_ctx_Used)
  {
    UNITY_TEST_ASSERT_NOT_NULL(ctx, cmock_line, CMockStringPtrIsNULL);
    CMOCK_MEMCPY((void*)ctx, (const void*)cmock_call_instance->ReturnThruPtr_ctx_Val,
      cmock_call_instance->ReturnThruPtr_ctx_Size);
  }
  UNITY_CLR_DETAILS();
  return cmock_call_instance->ReturnVal;
}

